function item(stockKey,labelKey,unitKey,points,options={}){return{id:options.id||stockKey,stockKey,labelKey,unitKey,points,scarcity:options.scarcity??2,progression:options.progression??2,eco:options.eco??2,quick:options.quick||[1,10,100],defaultReserve:options.defaultReserve??0,speedup:options.speedup??false,incentive:options.incentive??false,n:options.n??null,dailyMax:Number.isFinite(options.dailyMax)?Math.max(0,Math.floor(options.dailyMax)):null};}
function speedItem(stockKey,labelKey,points,options={}){return item(stockKey,labelKey,'minute',points,{...options,speedup:true,quick:[60,480,1440]});}
function resourceIcon(item){
  const key=String(item?.stockKey||item?.id||'');
  if(key==='stamina')return'⚡';
  if(key==='radarTasks')return'📡';
  if(key==='heroExp')return'⭐';
  if(key==='droneData')return'💾';
  if(key==='droneParts')return'⚙️';
  if(key.includes('Diamonds'))return'💎';
  if(key==='foodLots')return'🌾';
  if(key==='ironLots')return'🔩';
  if(key==='coinLots')return'🪙';
  if(key==='skillChipPremium')return'🧩';
  if(key.includes('Shards'))return key==='urShards'?'🟨':key==='ssrShards'?'🟪':'🔷';
  if(key.includes('Speed'))return'⏱️';
  if(key==='buildingPower')return'🏗️';
  if(key==='techPower')return'🔬';
  if(key==='urTrucks')return'🚚';
  if(key==='legendTasks')return'📋';
  if(key==='survivorRecruit')return'👥';
  if(key==='valorBadges')return'🛡️';
  if(key.includes('Chest'))return'🎁';
  if(key==='eliteTickets')return'🎟️';
  if(key==='skillMedals')return'🏅';
  if(key==='weaponShards')return'🔧';
  if(key.startsWith('trainT'))return'🪖';
  if(key.includes('KillT'))return'⚔️';
  if(key.startsWith('lostT'))return'🩹';
  return'📦';
}
function resourceImage(item,compact=false){return`<span class="resource-image ${compact?'compact':''}" role="img" aria-label="${escapeHtml(itemLabel(item))}">${resourceIcon(item)}</span>`;}

