function detectLanguage(){const code=(navigator.language||'fr').toLowerCase().split('-')[0];return LANGS[code]?code:'fr';}
function automaticDay(){const d=new Date().getDay();return d===0?1:Math.min(6,d);}
function todayKey(){return new Date().toISOString().slice(0,10);}
function defaultState(){return{version:VERSION,language:detectLanguage(),view:'scanner',selectedDay:automaticDay(),autoDay:true,lastOpenDate:todayKey(),profile:{playerName:'',target:7200000,margin:300000,bonusPct:100,pointProfile:'advanced',strategy:'economy',economyWeek:false,speedupLimitDays:10},currentPoints:{},inventory:{},reserves:{},pointOverrides:{},planAdjustments:{},expOnlyAccepted:{},inventorySnapshots:{},inventoryHistory:[],simpleSelections:{},lastPlan:null};}
function deepMerge(base,extra){if(!extra||typeof extra!=='object')return base;for(const[k,v]of Object.entries(extra)){if(v&&typeof v==='object'&&!Array.isArray(v)&&base[k]&&typeof base[k]==='object')base[k]=deepMerge(base[k],v);else base[k]=v;}return base;}
function loadState(){try{const saved=JSON.parse(localStorage.getItem(STORAGE_KEY)||'null')||{};const merged=deepMerge(defaultState(),saved);if(saved.version!==VERSION){merged.version=VERSION;merged.view='scanner';if(!saved.profile||saved.profile.pointProfile==='standard')merged.profile.pointProfile='advanced';}return merged;}catch{return defaultState();}}
