const at=(key,vars={})=>{let value=(ADJUST_TEXT[state.language]||ADJUST_TEXT.fr)[key]??ADJUST_TEXT.en[key]??ADJUST_TEXT.fr[key]??key;for(const[k,v]of Object.entries(vars))value=String(value).replaceAll(`{${k}}`,v);return value;};
const it=(key,vars={})=>{let value=(INVENTORY_TEXT[state.language]||INVENTORY_TEXT.fr)[key]??INVENTORY_TEXT.en[key]??INVENTORY_TEXT.fr[key]??key;for(const[k,v]of Object.entries(vars))value=String(value).replaceAll(`{${k}}`,v);return value;};
const pt=(key,vars={})=>{let value=(POINT_BOX_TEXT[state.language]||POINT_BOX_TEXT.fr)[key]??POINT_BOX_TEXT.en[key]??POINT_BOX_TEXT.fr[key]??key;for(const[k,v]of Object.entries(vars))value=String(value).replaceAll(`{${k}}`,v);return value;};
const apt=(key,vars={})=>{let value=(AUTO_PLAN_TEXT[state.language]||AUTO_PLAN_TEXT.fr)[key]??AUTO_PLAN_TEXT.en[key]??AUTO_PLAN_TEXT.fr[key]??key;for(const[k,v]of Object.entries(vars))value=String(value).replaceAll(`{${k}}`,v);return value;};
const fmt=n=>new Intl.NumberFormat(LOCALES[state.language]||'fr-FR',{maximumFractionDigits:0}).format(Number(n)||0);
const fmtPointValue=n=>new Intl.NumberFormat(LOCALES[state.language]||'fr-FR',{maximumFractionDigits:Math.abs(Number(n)||0)<1?4:2}).format(Number(n)||0);
const fmtDate=value=>{if(!value)return it('noReference');try{return new Intl.DateTimeFormat(LOCALES[state.language]||'fr-FR',{dateStyle:'short',timeStyle:'short'}).format(new Date(value));}catch{return String(value);}};
const day=()=>DAYS.find(d=>d.id===Number(state.selectedDay))||DAYS[0];
const dayText=(id=state.selectedDay)=>(DAY_TEXT[state.language]||DAY_TEXT.fr)[Number(id)-1];
const pointKey=(dayId,itemId)=>`${dayId}:${itemId}`;
const getStock=i=>Math.max(0,Number(state.inventory[i.stockKey]||0));
const getReserve=i=>state.reserves[i.stockKey]===undefined?Number(i.defaultReserve||0):Math.max(0,Number(state.reserves[i.stockKey]||0));
const getPoints=(dayId,i)=>state.pointOverrides[pointKey(dayId,i.id)]===undefined?Number(i.points):Math.max(0,Number(state.pointOverrides[pointKey(dayId,i.id)]||0));
const pointProfileMultiplier=i=>{const profile=state.profile.pointProfile||'standard';if(profile==='base')return 1;if(profile==='standard')return 2+(i.incentive?0.5:0);if(profile==='advanced')return 2.5+(i.incentive?0.5:0);return 1+Math.max(0,Number(state.profile.bonusPct||0))/100;};
