function applyTranslations(){document.documentElement.lang=state.language;document.title='GoMo VS Planner';document.querySelectorAll('[data-i18n]').forEach(node=>node.textContent=t(node.dataset.i18n));document.querySelectorAll('[data-i18n-placeholder]').forEach(node=>node.placeholder=t(node.dataset.i18nPlaceholder));document.querySelectorAll('[data-adjust-i18n]').forEach(node=>node.textContent=at(node.dataset.adjustI18n));el('languageSelect').innerHTML=Object.entries(LANGS).map(([k,v])=>`<option value="${k}">${v}</option>`).join('');el('languageSelect').value=state.language;el('strategy').innerHTML=[['economy','strategyEconomy'],['prudent','strategyPrudent'],['progress','strategyProgress'],['score','strategyScore']].map(([v,k])=>`<option value="${v}">${t(k)}</option>`).join('');el('strategy').value=state.profile.strategy;renderCoverTranslations();renderWorkflowTranslations();renderSmartHelpTranslations();renderEconomyWeek();renderOcrTranslations();renderSimpleTranslations();renderUltraTranslations();renderInventoryTranslations();renderPointBoxTranslations();renderAutoTranslations();renderPointProfile();}
function renderAll(){applyTranslations();renderView();renderProfile();renderDays();renderDayInfo();renderResources();renderSummary();renderSimplePoints();renderGuide();renderStrategyHelp();renderScanner();renderInventoryStatus();renderInventoryComparison();if(state.view==='planner')renderLastPlan();else{el('resultPanel')?.classList.add('hidden');el('quickResultPanel')?.classList.add('hidden');}}
function renderView(){const valid=['scanner','guide','settings'];if(!valid.includes(state.view))state.view='scanner';document.querySelectorAll('.view').forEach(v=>v.classList.remove('active'));document.querySelectorAll('.nav-btn').forEach(b=>b.classList.toggle('active',b.dataset.view===state.view));el(`${state.view}View`).classList.add('active');}
function renderProfile(){el('playerName').value=state.profile.playerName||'';el('targetPoints').value=Number(state.profile.target||0);el('marginPoints').value=Number(state.profile.margin||0);el('bonusPct').value=Number(state.profile.bonusPct||0);el('strategy').value=state.profile.strategy||'economy';el('speedupLimitDays').value=Number(state.profile.speedupLimitDays??10);const current=Number(state.currentPoints[state.selectedDay]||0);el('currentPoints').value=current;el('quickCurrentPoints').value=current;el('autoDay').checked=Boolean(state.autoDay);el('quickAutoDay').checked=Boolean(state.autoDay);renderPointProfile();}
