function renderDayInfo(){const tx=dayText();el('dayEyebrow').textContent=`${t('day')} ${state.selectedDay}`;el('dayTitle').textContent=tx.title;el('dayDescription').textContent=tx.description;el('useToday').textContent=tx.use;el('saveForLater').textContent=tx.save;}
function quickLabel(amount,i){if(i.speedup){if(amount===1440)return`+1 ${t('daysUnit')}`;if(amount>=60&&amount%60===0)return`+${amount/60}${t('hours')}`;}if(amount>=1000000)return`+${(amount/1000000).toLocaleString(LOCALES[state.language],{maximumFractionDigits:1})}M`;if(amount>=1000)return`+${(amount/1000).toLocaleString(LOCALES[state.language],{maximumFractionDigits:1})}K`;return`+${amount}`;}
function renderResources(){const d=day();el('resourceList').innerHTML=d.items.map(i=>{const p=effectivePoints(d.id,i),potential=usable(i)*p;return`<article class="resource-card" data-item="${escapeHtml(i.id)}"><div class="resource-head"><div class="resource-title-with-image">${resourceImage(i)}<div><h3>${escapeHtml(itemLabel(i))}</h3><p class="resource-meta">${t('unit')}: ${escapeHtml(itemUnit(i))}</p></div></div><div class="resource-potential">${fmt(Math.floor(potential))} pts</div></div><div class="resource-fields"><label class="resource-field"><span>${t('stock')}</span><input class="inventory-input" data-stock="${escapeHtml(i.stockKey)}" type="number" inputmode="decimal" min="0" value="${getStock(i)}"></label><label class="resource-field"><span>${t('reserve')}</span><input class="reserve-input" data-stock="${escapeHtml(i.stockKey)}" type="number" inputmode="decimal" min="0" value="${getReserve(i)}"></label><label class="resource-field points-field"><span>${t('pointsPerUnit')}</span><input class="points-input" data-point-key="${pointKey(d.id,i.id)}" type="number" inputmode="decimal" min="0" step="any" value="${getPoints(d.id,i)}"></label></div><div class="quick-row">${i.quick.map(a=>`<button class="quick-btn" data-add="${a}" data-stock="${escapeHtml(i.stockKey)}">${quickLabel(a,i)}</button>`).join('')}<button class="quick-btn" data-clear-stock="${escapeHtml(i.stockKey)}">0</button></div><div class="resource-foot"><span>${t('usable')}: <strong>${fmt(Math.floor(usable(i)))}</strong></span><span>${t('potential')}: <strong>${fmt(Math.floor(potential))} pts</strong></span></div></article>`;}).join('');}
function renderSummary(){const d=day(),current=Number(state.currentPoints[d.id]||0),goal=target(),missing=Math.max(0,goal-current),potential=d.items.reduce((sum,i)=>sum+usable(i)*effectivePoints(d.id,i),0);el('recommendedTarget').textContent=fmt(goal);el('currentPointsSummary').textContent=fmt(current);el('missingPointsSummary').textContent=fmt(missing);el('potentialPointsSummary').textContent=fmt(Math.floor(potential));const quickTarget=el('quickRecommendedTarget');if(quickTarget)quickTarget.textContent=fmt(goal);}
