function renderStrategyHelp(){el('strategyHelp').textContent=t({economy:'helpEconomy',prudent:'helpPrudent',progress:'helpProgress',score:'helpScore'}[state.profile.strategy]||'helpEconomy');}

function strategyComparator(strategy){return(a,b)=>{if(strategy==='saveWeek'){const importance=x=>x.item.scarcity*100+x.item.eco*45+x.item.progression*25;return(importance(a)-importance(b))||(b.ppu-a.ppu);}if(strategy==='score')return(b.ppu-a.ppu)||(a.item.scarcity-b.item.scarcity);if(strategy==='progress')return(b.item.progression-a.item.progression)||(a.item.scarcity-b.item.scarcity)||(b.ppu-a.ppu);if(strategy==='prudent')return(a.item.scarcity-b.item.scarcity)||(a.item.eco-b.item.eco)||(b.ppu-a.ppu);return(a.item.eco-b.item.eco)||(a.item.scarcity-b.item.scarcity)||(b.ppu-a.ppu);};}
function strategyCost(c,strategy,qty){const scarcity=c.item.scarcity*5000,action=Math.min(qty,100000)*.01;if(strategy==='saveWeek')return c.item.scarcity*12000+c.item.eco*5000+c.item.progression*2500+action;if(strategy==='score')return c.item.scarcity*100;if(strategy==='progress')return(6-c.item.progression)*4000+c.item.scarcity*1000;if(strategy==='prudent')return scarcity*2+c.item.eco*2500+action;return scarcity+c.item.eco*1500+action;}
function dayAdjustments(dayId=state.selectedDay){const key=String(dayId);if(!state.planAdjustments||typeof state.planAdjustments!=='object')state.planAdjustments={};if(!state.planAdjustments[key]||typeof state.planAdjustments[key]!=='object')state.planAdjustments[key]={fixed:{},excluded:{}};const a=state.planAdjustments[key];if(!a.fixed||typeof a.fixed!=='object')a.fixed={};if(!a.excluded||typeof a.excluded!=='object')a.excluded={};return a;}
function calculatePlan(){
  const d=day(),current=Number(state.currentPoints[d.id]||0),goal=target(),needed=Math.max(0,goal-current),speedLimit=state.view==='scanner'?Number.POSITIVE_INFINITY:Math.max(0,Number(state.profile.speedupLimitDays||0)*1440),adjustments=dayAdjustments(d.id),activeStrategy=state.profile.economyWeek?'saveWeek':state.profile.strategy;
  let speedUsed=0;
  if(needed<=0)return{dayId:d.id,goal,current,totalPoints:0,finalPoints:current,steps:[],reached:true,overshoot:current-goal,missing:0,strategy:state.profile.strategy,speedUsed:0};
  const candidates=d.items.map(i=>({item:i,available:Math.floor(usable(i)),ppu:effectivePoints(d.id,i)})).filter(c=>c.available>0&&c.ppu>0).sort(strategyComparator(activeStrategy));
  const usage=new Map();let remaining=needed;
  for(const c of candidates){
    if(adjustments.excluded[c.item.id])continue;
    if(!Object.prototype.hasOwnProperty.call(adjustments.fixed,c.item.id))continue;
    let qty=Math.max(0,Math.min(c.available,Math.floor(Number(adjustments.fixed[c.item.id])||0)));
    if(c.item.speedup)qty=Math.min(qty,Math.max(0,Math.floor(speedLimit-speedUsed)));
    usage.set(c.item.id,qty);remaining-=qty*c.ppu;if(c.item.speedup)speedUsed+=qty;
  }
  const automatic=candidates.filter(c=>!adjustments.excluded[c.item.id]&&!Object.prototype.hasOwnProperty.call(adjustments.fixed,c.item.id));
  if(remaining>.0001){for(const c of automatic){let max=c.available;if(c.item.speedup)max=Math.min(max,Math.max(0,Math.floor(speedLimit-speedUsed)));if(max<=0)continue;const qty=Math.min(max,Math.floor(remaining/c.ppu));if(qty>0){usage.set(c.item.id,qty);remaining-=qty*c.ppu;if(c.item.speedup)speedUsed+=qty;}if(remaining<=.0001)break;}}
  if(remaining>.0001){let best=null;for(const c of automatic){const used=usage.get(c.item.id)||0;let left=c.available-used;if(c.item.speedup)left=Math.min(left,Math.max(0,Math.floor(speedLimit-speedUsed)));if(left<=0)continue;const qty=Math.min(left,Math.ceil(remaining/c.ppu));if(qty<=0)continue;const gained=qty*c.ppu,rank=Math.max(0,gained-remaining)+strategyCost(c,activeStrategy,qty);if(!best||rank<best.rank)best={c,qty,gained,rank};}if(best){usage.set(best.c.item.id,(usage.get(best.c.item.id)||0)+best.qty);remaining-=best.gained;if(best.c.item.speedup)speedUsed+=best.qty;}}
  if(remaining>.0001){for(const c of automatic){const used=usage.get(c.item.id)||0;let left=c.available-used;if(c.item.speedup)left=Math.min(left,Math.max(0,Math.floor(speedLimit-speedUsed)));if(left<=0)continue;usage.set(c.item.id,used+left);remaining-=left*c.ppu;if(c.item.speedup)speedUsed+=left;if(remaining<=.0001)break;}}
  const steps=candidates.map(c=>{const qty=usage.get(c.item.id)||0;if(!qty)return null;return{itemId:c.item.id,stockKey:c.item.stockKey,qty,points:qty*c.ppu,remainingStock:Math.max(0,getStock(c.item)-qty),speedup:c.item.speedup};}).filter(Boolean);
  const totalPoints=steps.reduce((s,x)=>s+x.points,0),finalPoints=current+totalPoints;
  return{dayId:d.id,goal,current,totalPoints,finalPoints,steps,reached:finalPoints>=goal,overshoot:Math.max(0,finalPoints-goal),missing:Math.max(0,goal-finalPoints),strategy:state.profile.strategy,speedUsed};
}
function findItem(id,dayId=state.selectedDay){return(DAYS.find(d=>d.id===Number(dayId))||day()).items.find(i=>i.id===id);}
function compactGameAmount(value){const n=Math.max(0,Number(value)||0),locale=LOCALES[state.language]||LOCALES.fr;if(n>=1e9)return`${(n/1e9).toLocaleString(locale,{maximumFractionDigits:2})} G`;if(n>=1e6)return`${(n/1e6).toLocaleString(locale,{maximumFractionDigits:2})} M`;if(n>=1e3)return`${(n/1e3).toLocaleString(locale,{maximumFractionDigits:1})} K`;return fmt(n);}
function formatQty(qty,i){if(i.speedup){const days=Math.floor(qty/1440),hours=Math.floor((qty%1440)/60),minutes=Math.floor(qty%60),parts=[];if(days)parts.push(`${days} ${t('daysUnit')}`);if(hours)parts.push(`${hours}${t('hours')}`);if(minutes)parts.push(`${minutes} ${t('minutes')}`);return parts.join(' ')||`0 ${t('minutes')}`;}if(i.unitKey==='exp')return`${compactGameAmount(qty)} EXP`;return`${fmt(qty)} ${itemUnit(i)}`;}
function adjustmentStep(i){return Math.max(1,Math.floor(Number(i.quick?.[0])||1));}
function renderAdjustablePlan(plan,containerId){
  const box=el(containerId);if(!box)return;const d=DAYS.find(x=>x.id===Number(plan.dayId))||day(),adjustments=dayAdjustments(plan.dayId),stepMap=new Map(plan.steps.map(s=>[s.itemId,s]));
  const visible=d.items.filter(i=>usable(i)>0||stepMap.has(i.id)||Object.prototype.hasOwnProperty.call(adjustments.fixed,i.id)||adjustments.excluded[i.id]);
  if(!visible.length){box.innerHTML=`<p class="plan-empty">${escapeHtml(at('noAvailable'))}</p>`;return;}
  visible.sort((a,b)=>(Number(stepMap.has(b.id))-Number(stepMap.has(a.id)))||(a.eco-b.eco)||(a.scarcity-b.scarcity));
  box.innerHTML=visible.map(i=>{const s=stepMap.get(i.id),qty=Math.max(0,Math.floor(s?.qty||0)),max=Math.max(0,Math.floor(usable(i))),ppu=effectivePoints(plan.dayId,i),fixed=Object.prototype.hasOwnProperty.call(adjustments.fixed,i.id),excluded=Boolean(adjustments.excluded[i.id]),status=excluded?at('disabled'):(fixed?at('manual'):at('automatic')),statusClass=excluded?'disabled':(fixed?'manual':'automatic'),inc=adjustmentStep(i);return`<article class="plan-adjust-row ${excluded?'is-disabled':''}" data-plan-item="${escapeHtml(i.id)}"><div class="plan-adjust-main"><div class="plan-adjust-name"><h3>${escapeHtml(itemLabel(i))}</h3><p>${escapeHtml(at('pointsValue'))}: <strong>${fmtPointValue(ppu)} ${escapeHtml(t('points'))}</strong> / ${escapeHtml(itemUnit(i))}</p></div><span class="plan-mode-badge ${statusClass}">${escapeHtml(status)}</span></div><div class="plan-adjust-controls"><button class="plan-step-btn" data-plan-delta="-${inc}" aria-label="-">−</button><label><span>${escapeHtml(at('planned'))}</span><input class="plan-qty-input" type="number" inputmode="decimal" min="0" max="${max}" step="${inc}" value="${qty}"></label><button class="plan-step-btn" data-plan-delta="${inc}" aria-label="+">+</button></div><div class="plan-adjust-foot"><span>${escapeHtml(at('resourcePoints'))}: <strong>${fmt(Math.floor(qty*ppu))}</strong></span><span>${escapeHtml(at('available'))}: <strong>${fmt(max)}</strong></span><button class="plan-exclude-btn ${excluded?'active':''}" data-plan-exclude>${escapeHtml(excluded?at('include'):at('exclude'))}</button></div></article>`;}).join('');
}
function recalculateAdjustedPlan(scroll=false){const plan=calculatePlan();state.lastPlan=plan;saveState(at('adjusted'));renderPlan(plan,false);renderQuickPlan(plan,scroll);}
function setPlanQuantity(itemId,value){const i=findItem(itemId);if(!i)return;const a=dayAdjustments(),max=Math.max(0,Math.floor(usable(i))),qty=Math.max(0,Math.min(max,Math.floor(Number(value)||0)));a.excluded[itemId]=false;a.fixed[itemId]=qty;recalculateAdjustedPlan(false);}
