let smartHelpTargetId='simplePhotoStep';
function smartHelpAdvice(){
  const tx=SMART_HELP_TEXT[state.language]||SMART_HELP_TEXT.fr,plan=calculatePlan(),available=inventoryPotential(state.selectedDay,true);
  if(Number(plan.current)>=Number(plan.goal))return{message:tx.reached,action:tx.plan,target:'simplePointsPanel'};
  if(available<=0)return{message:tx.noInventory,action:tx.photos,target:'simplePhotoStep'};
  if(!plan.reached)return{message:tx.missing,action:tx.resources,target:'simpleResourceStep'};
  return{message:tx.ready,action:tx.plan,target:'simplePointsPanel'};
}
