function answerExpOnlyChoice(choice){const plan=currentAssistantPlan();if(!expOnlyPlan(plan))return;if(!state.expOnlyAccepted||typeof state.expOnlyAccepted!=='object')state.expOnlyAccepted={};const key=String(plan.dayId);if(choice==='yes')state.expOnlyAccepted[key]=Number(plan.steps[0].qty||0);else{delete state.expOnlyAccepted[key];const a=dayAdjustments(plan.dayId);a.excluded[plan.steps[0].itemId]=true;delete a.fixed[plan.steps[0].itemId];}state.lastPlan=calculatePlan();saveState();renderSimplePoints();}

