function renderInventoryTranslations(){document.querySelectorAll('[data-inv-i18n]').forEach(node=>node.textContent=it(node.dataset.invI18n));}
function dayById(dayId){return DAYS.find(d=>d.id===Number(dayId))||DAYS[0];}
function dayItemByStockKey(dayId,stockKey){return dayById(dayId).items.find(i=>i.stockKey===stockKey)||null;}
function dayStockKeys(dayId){return[...new Set(dayById(dayId).items.map(i=>i.stockKey))];}
function inventoryQuantities(dayId){return Object.fromEntries(dayStockKeys(dayId).map(k=>[k,Math.max(0,Number(state.inventory[k]||0))]));}
function inventoryPotential(dayId,protectReserves=false){const d=dayById(dayId);return d.items.reduce((sum,i)=>{const qty=protectReserves?Math.max(0,getStock(i)-getReserve(i)):getStock(i);return sum+qty*effectivePoints(d.id,i);},0);}
function saveInventorySnapshot(dayId,quantities=inventoryQuantities(dayId),source='manual'){state.inventorySnapshots[String(dayId)]={dayId:Number(dayId),capturedAt:new Date().toISOString(),source,quantities:{...quantities}};}
function addInventoryHistory(entry){state.inventoryHistory=[{id:`${Date.now()}-${Math.random().toString(36).slice(2,7)}`,createdAt:new Date().toISOString(),...entry},...(Array.isArray(state.inventoryHistory)?state.inventoryHistory:[])].slice(0,60);}
function latestInventoryHistory(dayId){return(Array.isArray(state.inventoryHistory)?state.inventoryHistory:[]).find(h=>Number(h.dayId)===Number(dayId)&&Number(h.points)>0)||null;}
function inventoryEntryLabel(type){return it(type==='comparison'?'comparisonEntry':type==='plan'?'planEntry':'baselineEntry');}
function renderInventoryStatus(){const box=el('inventoryStatusPanel');if(!box)return;const dayId=state.selectedDay,snapshot=state.inventorySnapshots[String(dayId)],latest=latestInventoryHistory(dayId),full=inventoryPotential(dayId,false),usableTotal=inventoryPotential(dayId,true);el('inventoryTotalPoints').textContent=fmt(Math.floor(full));el('inventoryUsablePoints').textContent=fmt(Math.floor(usableTotal));el('inventoryReferenceDate').textContent=snapshot?fmtDate(snapshot.capturedAt):it('noReference');el('inventoryLastDetected').textContent=latest&&Number(latest.points)>0?`${fmt(Math.floor(latest.points))} ${t('points')}`:'0';el('clearReferenceBtn').disabled=!snapshot;const history=(Array.isArray(state.inventoryHistory)?state.inventoryHistory:[]).filter(h=>Number(h.dayId)===Number(dayId)).slice(0,4);el('inventoryHistoryList').innerHTML=history.length?history.map(h=>`<article class="inventory-history-row"><div><strong>${escapeHtml(inventoryEntryLabel(h.type))}</strong><span>${escapeHtml(fmtDate(h.createdAt))}</span></div><div><strong>${fmt(Math.floor(h.points||0))} ${escapeHtml(t('points'))}</strong><span>${escapeHtml(it('resourcesChanged',{count:Number(h.changeCount||0)}))}</span></div></article>`).join(''):`<p class="inventory-empty">${escapeHtml(it('noHistory'))}</p>`;}
function buildInventoryComparison(dayId,grouped){const snapshot=state.inventorySnapshots[String(dayId)],resourceValues={};let explicitScore=null;for(const[k,v]of grouped){if(k==='__currentPoints')explicitScore=Math.max(0,Number(v)||0);else resourceValues[k]=Math.max(0,Number(v)||0);}if(!snapshot)return{first:true,dayId:Number(dayId),resourceValues,explicitScore};const rows=Object.entries(resourceValues).map(([stockKey,newQty])=>{const item=dayItemByStockKey(dayId,stockKey);if(!item)return null;const oldQty=Math.max(0,Number(snapshot.quantities?.[stockKey]??state.inventory[stockKey]??0)),usedQty=Math.max(0,oldQty-newQty),receivedQty=Math.max(0,newQty-oldQty),ppu=effectivePoints(dayId,item);return{stockKey,itemId:item.id,oldQty,newQty,usedQty,receivedQty,ppu,points:usedQty*ppu};}).filter(Boolean);return{first:false,dayId:Number(dayId),resourceValues,explicitScore,rows};}
function comparisonPointTotal(){if(!pendingInventoryComparison||pendingInventoryComparison.first)return 0;return pendingInventoryComparison.rows.reduce((sum,r)=>sum+Math.max(0,Number(r.usedQty)||0)*r.ppu,0);}
function comparisonRestockTotal(){if(!pendingInventoryComparison||pendingInventoryComparison.first)return 0;return pendingInventoryComparison.rows.reduce((sum,r)=>sum+Math.max(0,Number(r.receivedQty)||0),0);}
function renderInventoryComparison(){const panel=el('inventoryComparisonPanel');if(!panel)return;const c=pendingInventoryComparison;if(!c||c.first){panel.classList.add('hidden');return;}panel.classList.remove('hidden');const points=comparisonPointTotal();el('inventoryComparisonBadge').textContent=`${fmt(Math.floor(points))} ${t('points')}`;el('inventoryComparisonRows').innerHTML=c.rows.length?c.rows.map((r,index)=>{const item=dayItemByStockKey(c.dayId,r.stockKey);return`<article class="inventory-compare-row" data-compare-index="${index}"><div class="inventory-compare-name"><h3>${escapeHtml(item?itemLabel(item):r.stockKey)}</h3><span>${fmtPointValue(r.ppu)} ${escapeHtml(t('points'))} / ${escapeHtml(item?itemUnit(item):'')}</span></div><div class="inventory-stock-pair"><span>${escapeHtml(it('oldStock'))}<strong>${fmt(r.oldQty)}</strong></span><span>${escapeHtml(it('newStock'))}<strong>${fmt(r.newQty)}</strong></span></div><label><span>${escapeHtml(it('usedQty'))}</span><input class="inventory-used-input" type="number" inputmode="decimal" min="0" max="${r.oldQty}" value="${r.usedQty}"></label><div class="inventory-row-points"><span>${escapeHtml(it('resourcePoints'))}</span><strong>${fmt(Math.floor(r.usedQty*r.ppu))}</strong></div></article>`;}).join(''):`<p class="inventory-empty">${escapeHtml(it('noConsumption'))}</p>`;const note=el('inventoryComparisonNote');const notes=[it('partialScanNote'),c.explicitScore!==null?it('photoScoreUsed'):it('manualPointsUsed')];if(comparisonRestockTotal()>0)notes.push(it('restocked'));note.textContent=notes.join(' ');el('confirmInventoryComparisonBtn').disabled=c.rows.length===0;}
function applyRecognisedInventory(dayId,resourceValues){for(const[k,v]of Object.entries(resourceValues))state.inventory[k]=Math.max(0,Number(v)||0);}
function mergedSnapshotQuantities(dayId,resourceValues){const old=state.inventorySnapshots[String(dayId)]?.quantities||inventoryQuantities(dayId);return{...old,...resourceValues};}
function finalizeFirstInventoryComparison(c){applyRecognisedInventory(c.dayId,c.resourceValues);resetSimpleSelections(c.dayId);if(c.explicitScore!==null)state.currentPoints[c.dayId]=Math.max(0,c.explicitScore);saveInventorySnapshot(c.dayId,mergedSnapshotQuantities(c.dayId,c.resourceValues),'photo');addInventoryHistory({dayId:c.dayId,type:'baseline',points:0,changeCount:Object.keys(c.resourceValues).length,changes:[]});state.selectedDay=c.dayId;state.autoDay=false;invalidatePlan();state.lastPlan=calculatePlan();state.view='scanner';saveState();pendingInventoryComparison=null;renderAll();renderQuickPlan(state.lastPlan,true);showToast(it('firstReferenceSaved'));}
function finalizeInventoryComparison(addPoints=true){const c=pendingInventoryComparison;if(!c||c.first)return;applyRecognisedInventory(c.dayId,c.resourceValues);resetSimpleSelections(c.dayId);const changes=c.rows.map(r=>({...r,usedQty:Math.max(0,Math.min(r.oldQty,Number(r.usedQty)||0)),points:Math.max(0,Math.min(r.oldQty,Number(r.usedQty)||0))*r.ppu})),detectedPoints=changes.reduce((sum,r)=>sum+r.points,0),previousPoints=Math.max(0,Number(state.currentPoints[c.dayId]||0));let addedPoints=0;if(addPoints){if(c.explicitScore!==null){state.currentPoints[c.dayId]=Math.max(0,c.explicitScore);addedPoints=Math.max(0,state.currentPoints[c.dayId]-previousPoints);}else{addedPoints=detectedPoints;state.currentPoints[c.dayId]=previousPoints+addedPoints;}addInventoryHistory({dayId:c.dayId,type:'comparison',points:addedPoints,changeCount:changes.filter(r=>r.usedQty>0).length,changes});}else addInventoryHistory({dayId:c.dayId,type:'baseline',points:0,changeCount:Object.keys(c.resourceValues).length,changes:[]});saveInventorySnapshot(c.dayId,mergedSnapshotQuantities(c.dayId,c.resourceValues),'photo');state.selectedDay=c.dayId;state.autoDay=false;pendingInventoryComparison=null;invalidatePlan();state.lastPlan=calculatePlan();state.view='scanner';saveState();renderAll();renderQuickPlan(state.lastPlan,true);showToast(addPoints?it('comparisonApplied',{points:fmt(Math.floor(addedPoints))}):it('referenceUpdated'));}
function saveCurrentInventoryReference(){const dayId=state.selectedDay;saveInventorySnapshot(dayId,inventoryQuantities(dayId),'manual');addInventoryHistory({dayId,type:'baseline',points:0,changeCount:dayStockKeys(dayId).filter(k=>Number(state.inventory[k]||0)>0).length,changes:[]});saveState();renderInventoryStatus();showToast(it('referenceSaved'));}
function clearCurrentInventoryReference(){const dayId=state.selectedDay;confirmAction(it('clearReferenceTitle'),it('clearReferenceMessage'),()=>{delete state.inventorySnapshots[String(dayId)];pendingInventoryComparison=null;saveState();renderAll();showToast(it('referenceCleared'));});}
function syncSnapshotAfterPlan(plan){const before=state.inventorySnapshots[String(plan.dayId)]?.quantities||{};const changes=plan.steps.map(s=>{const item=findItem(s.itemId,plan.dayId),oldQty=Math.max(0,Number(before[s.stockKey]??(Number(state.inventory[s.stockKey]||0)+Number(s.qty||0)))),newQty=Math.max(0,Number(state.inventory[s.stockKey]||0));return{stockKey:s.stockKey,itemId:s.itemId,oldQty,newQty,usedQty:s.qty,receivedQty:0,ppu:item?effectivePoints(plan.dayId,item):0,points:s.points};});saveInventorySnapshot(plan.dayId,inventoryQuantities(plan.dayId),'plan');addInventoryHistory({dayId:plan.dayId,type:'plan',points:plan.totalPoints,changeCount:changes.length,changes});}


function renderAutoScanStatus(){const panel=el('autoScanStatus');if(!panel)return;if(!lastAutoScanSummary){panel.classList.add('hidden');return;}panel.classList.remove('hidden');el('autoScanBadge').textContent=apt('scanBadge');let text;if(lastAutoScanSummary.count>0&&lastAutoScanSummary.relevantCount===0){const notice={fr:`${lastAutoScanSummary.count} ressource(s) reconnue(s) et enregistrée(s), mais aucune n'apporte de points pour le jour VS sélectionné.`,en:`${lastAutoScanSummary.count} resource(s) recognised and saved, but none scores points on the selected VS day.`,de:`${lastAutoScanSummary.count} Ressource(n) erkannt und gespeichert, aber keine bringt am gewählten VS-Tag Punkte.`,ro:`${lastAutoScanSummary.count} resursă(e) recunoscută(e) și salvată(e), dar niciuna nu aduce puncte în ziua VS selectată.`,uk:`Розпізнано і збережено ресурсів: ${lastAutoScanSummary.count}, але жоден не дає очок у вибраний день VS.`,ko:`${lastAutoScanSummary.count}개 자원을 인식해 저장했지만 선택한 VS 요일에는 점수가 없습니다.`,hr:`Prepoznato i spremljeno resursa: ${lastAutoScanSummary.count}, ali nijedan ne donosi bodove odabranog VS dana.`};text=notice[state.language]||notice.fr;}else text=apt('scanSummary',{count:lastAutoScanSummary.count});if(lastAutoScanSummary.addedPoints>0)text+=apt('scanSummaryPoints',{points:fmt(Math.floor(lastAutoScanSummary.addedPoints))});el('autoScanSummary').textContent=text;}
function groupedAutomaticOcrValues(){const valid=ocrRows.filter(r=>r.enabled&&r.target&&r.confidence>=55&&Number(r.value)>=0),grouped=new Map(),summed=new Map();for(const row of valid){const value=Math.max(0,Number(row.value)||0);if(row.combine==='sum'){summed.set(row.target,(summed.get(row.target)||0)+value);continue;}grouped.set(row.target,Math.max(grouped.get(row.target)||0,value));}for(const[target,value]of summed)grouped.set(target,(grouped.get(target)||0)+value);return grouped;}
function autoApplyOcrRows(){const grouped=groupedAutomaticOcrValues();if(!grouped.size){showToast(ot('noDetectedValue'));return false;}const scanDay=Number(ocrDayId||state.selectedDay),comparison=buildInventoryComparison(scanDay,grouped),resourceValues=comparison.resourceValues||{},previous=Math.max(0,Number(state.currentPoints[scanDay]||0));let addedPoints=0;if(comparison.first){applyRecognisedInventory(scanDay,resourceValues);if(comparison.explicitScore!==null)state.currentPoints[scanDay]=Math.max(0,comparison.explicitScore);saveInventorySnapshot(scanDay,mergedSnapshotQuantities(scanDay,resourceValues),'photo');addInventoryHistory({dayId:scanDay,type:'baseline',points:0,changeCount:Object.keys(resourceValues).length,changes:[]});}else{const changes=comparison.rows.map(r=>({...r,usedQty:Math.max(0,Number(r.usedQty)||0),points:Math.max(0,Number(r.usedQty)||0)*r.ppu}));applyRecognisedInventory(scanDay,resourceValues);if(comparison.explicitScore!==null){state.currentPoints[scanDay]=Math.max(0,comparison.explicitScore);addedPoints=Math.max(0,state.currentPoints[scanDay]-previous);}else{addedPoints=changes.reduce((sum,r)=>sum+r.points,0);state.currentPoints[scanDay]=previous+addedPoints;}saveInventorySnapshot(scanDay,mergedSnapshotQuantities(scanDay,resourceValues),'photo');addInventoryHistory({dayId:scanDay,type:addedPoints>0?'comparison':'baseline',points:addedPoints,changeCount:changes.filter(r=>r.usedQty>0).length,changes});}state.selectedDay=scanDay;state.autoDay=false;state.planAdjustments[String(scanDay)]={fixed:{},excluded:{}};resetSimpleSelections(scanDay);invalidatePlan();state.lastPlan=calculatePlan();lastAutoScanSummary={count:Object.keys(resourceValues).length,relevantCount:Object.keys(resourceValues).filter(k=>dayStockKeys(scanDay).includes(k)).length,addedPoints};saveState();renderAll();setTimeout(()=>el('simplePointsPanel')?.scrollIntoView({behavior:'smooth',block:'start'}),80);showToast(ot('scanApplied'));return true;}

