function renderQuickPlan(plan,scroll=false){const panel=el('quickResultPanel');if(!panel)return;if(!plan||plan.dayId!==state.selectedDay){panel.classList.add('hidden');return;}panel.classList.remove('hidden');const strategyName=t({economy:'strategyEconomy',prudent:'strategyPrudent',progress:'strategyProgress',score:'strategyScore'}[plan.strategy]||'plan');el('quickResultTitle').textContent=`${dayText(plan.dayId).title} · ${strategyName}`;el('quickResultBadge').textContent=plan.reached?t('goalReached'):t('stockInsufficient');el('quickResultBadge').classList.toggle('warning',!plan.reached);el('quickResultMetrics').innerHTML=`<div class="metric"><span>${t('pointsAdded')}</span><strong>${fmt(Math.floor(plan.totalPoints))}</strong></div><div class="metric"><span>${t('estimatedTotal')}</span><strong>${fmt(Math.floor(plan.finalPoints))}</strong></div><div class="metric"><span>${plan.reached?t('realMargin'):t('missingPoints')}</span><strong>${fmt(Math.floor(plan.reached?plan.overshoot:plan.missing))}</strong></div>`;renderAdjustablePlan(plan,'quickPlanSteps');el('quickResultNote').textContent=plan.reached?t('reachedNote'):t('missingNote',{points:fmt(Math.ceil(plan.missing))});el('quickApplyPlanBtn').disabled=plan.steps.length===0;if(scroll)setTimeout(()=>panel.scrollIntoView({behavior:'smooth',block:'start'}),30);}
