function scannerTargetOptions(selected=''){const relevant=new Set(ocrDay().items.map(i=>i.stockKey)),unique=allOcrItems(),ordered=[...unique.entries()].sort(([a],[b])=>(Number(relevant.has(b))-Number(relevant.has(a)))||a.localeCompare(b));const options=[`<option value="">${escapeHtml(ot('ignore'))}</option>`,`<option value="__currentPoints" ${selected==='__currentPoints'?'selected':''}>${escapeHtml(ot('currentScore'))}</option>`];for(const[k,i]of ordered)options.push(`<option value="${escapeHtml(k)}" ${selected===k?'selected':''}>${escapeHtml(itemLabel(i))}</option>`);return options.join('');}
